from functools import cache

@cache
def fib(n: int) -> int:
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(10))

from collections.abc import Generator


def echo_round() -> Generator[int, float, str]:
    sent = yield 0
    while sent >= 0:
        sent = yield round(sent)
    return "Done"


iterator = echo_round()
next(iterator)
iterator.send(2.5)
try:
    iterator.send(-1.0)
except StopIteration as result:
    print(result.value)

